import type { DataSourceDbEntry, DataSourceDbEntryConfig } from "./datasources";
import { evolu } from './evolu/evolu_instance';
import { type AllDataSourcesQueryEntry, getDataSourcesQuery } from "./evolu/queries";
import { type DataSourceId, type InsertableDataSource } from "$lib/database/evolu/datastructure";
import { queryState } from "$lib/database/nodeRepository.svelte";

export function mapToDataSourceDbEntry(dbResult: AllDataSourcesQueryEntry) {
	return {
		id: dbResult.id,
		config: JSON.parse( dbResult.config ?? '{}' )
	} satisfies DataSourceDbEntry;
}

export const DataSourceRepository = {
	isReady() {
		return true;
	},

	addSource(dataSource: DataSourceDbEntryConfig): void {
		const newDataSource: InsertableDataSource = {
			config: {
				...dataSource
			}
		};
		evolu.insert('dataSources', newDataSource);
	},

	updateSource(dataSourceId: DataSourceId, dataSource: DataSourceDbEntryConfig): void {
		evolu.update('dataSources', {
			id: dataSourceId,
			config: {
				...dataSource
			}
		});
	},


	async getAllSourcesAsync(): Promise<DataSourceDbEntry[]> {
		const query = getDataSourcesQuery();
		const rows = await evolu.loadQuery(query);
		return rows.map(mapToDataSourceDbEntry);
	},

	getAllSourcesState() {
		return queryState(() => getDataSourcesQuery(), evolu, {
		useLoadQueryResult: true
	});
	},

	async getSourceByShort(short: string): Promise<DataSourceDbEntry> {
		const query = getDataSourcesQuery({
			short
		});
		const rows = await evolu.loadQuery(query);
		return rows.map(mapToDataSourceDbEntry)[0];
	},

	async getSource(sourceId: DataSourceId): Promise<DataSourceDbEntry> {
		const query = getDataSourcesQuery({
			id: sourceId
		});
		const rows = await evolu.loadQuery(query);

		return rows.map(mapToDataSourceDbEntry)[0];
	},

	deleteSource(sourceId: string): void {
		evolu.update('dataSources', { id: sourceId, isDeleted: true });
	},
};
