import {
	SqliteBoolean,
	id,
	nullOr,
	object,
	String,
	Number,
	json,
	JsonValue,
	type EvoluSchema,
	optional,
	record
} from '@evolu/common';
import type { Insertable, Updateable, Upsertable } from '@evolu/common/evolu';
import type { AnyType } from '@evolu/common';

export const NodeId = id('Node');
export type NodeId = typeof NodeId.Type;

export const UntypedJson = json(JsonValue, 'UntypedJson');

const GridChildNodeOptionsObject = object({
	col: Number,
	row: Number,
	colSpan: Number,
	rowSpan: Number
});

const jsonOptional = <T extends AnyType>(type: T) => optional(nullOr(type));

export const LayoutData = object({
	label: jsonOptional(String),
	elementProps: jsonOptional(
		object({
			// attributes?: HTMLAttributes<HTMLElement>;
			styleCss: jsonOptional(String)
		})
	),
	forParent: jsonOptional(
		object(
			{
				grid: jsonOptional(GridChildNodeOptionsObject),
				/**
				 * Custom Key used for templates to prevent dubplicate renders
				 */
				customKey: jsonOptional(String)
			},
			// additional unknown props
			record(String, JsonValue)
		)
	)
});

export type LayoutDataType = typeof LayoutData.Type;

export const LayoutDataJson = json(LayoutData, 'LayoutDataJson');

export type LayoutDataJson = typeof LayoutDataJson.Type;

export const SpecialFlagsJson = json(
	object({
		isRootNode: jsonOptional(SqliteBoolean)
	}),
	'SpecialFlagsJson'
);

export type SpecialFlagsJson = typeof SpecialFlagsJson.Type;

export const NodeDataId = id('NodeData');
export type NodeDataId = typeof NodeDataId.Type;

export const DataSourceId =id('DataSource');
export type DataSourceId = typeof DataSourceId.Type;

export const SettingId = id('Setting');
export type SettingId = typeof SettingId.Type;

export const Schema = {
	nodes: {
		id: NodeId,
		parentId: nullOr(NodeId),
		ofTemplate: SqliteBoolean,
		order: Number,
		type: String,
		layoutData: LayoutDataJson,
		nodeConfig: UntypedJson,
		specialFlags: nullOr(SpecialFlagsJson)
	},
	nodeData: {
		id: NodeDataId,
		nodeId: NodeId,
		subId: String, // this is forexample if you save data for a node withing a template, this will then be the generated id
		data: UntypedJson
	},
	dataSources: {
		id: DataSourceId,
		config: UntypedJson
	},
	globalStyles: {
		id: id('GlobalStyle'),
		style: UntypedJson
	},
	settings: {
		id: SettingId,
		key: String,
		value: UntypedJson
	}
} satisfies EvoluSchema;

export type InsertableNode = Insertable<(typeof Schema)['nodes']>;
export type UpdatableNode = Updateable<(typeof Schema)['nodes']>;

export type InsertableNodeData = Insertable<(typeof Schema)['nodeData']>;
export type UpdatableNodeData = Updateable<(typeof Schema)['nodeData']>;
export type UpsertableNodeData = Upsertable<(typeof Schema)['nodeData']>;


export type InsertableDataSource = Insertable<(typeof Schema)['dataSources']>;
export type UpdatableDataSource = Updateable<(typeof Schema)['dataSources']>;
export type UpsertableDataSource = Upsertable<(typeof Schema)['dataSources']>;


export type InsertableSetting = Insertable<(typeof Schema)['settings']>;
export type UpdatableSetting = Updateable<(typeof Schema)['settings']>;
export type UpsertableSetting = Upsertable<(typeof Schema)['settings']>;
