export const createCallbacks = (deps) => {
    const callbackMap = new Map();
    const callbacks = {
        register: (callback) => {
            const id = deps.nanoid();
            callbackMap.set(id, callback);
            return id;
        },
        execute: (id, arg) => {
            const callback = callbackMap.get(id);
            if (callback) {
                callbackMap.delete(id);
                callback(arg);
            }
        },
    };
    return callbacks;
};
