import { createNanoIdGenerator, loggerFactory } from "@evolu/common";
import { wrapWebWorker } from "../WebWorker.js";
import { appStateFactory } from "./AppStateFactory.js";
export const evoluWebDeps = {
    ...loggerFactory,
    ...appStateFactory,
    ...createNanoIdGenerator(),
    createDbWorker: () => wrapWebWorker(() => new Worker(new URL("Db.worker.js?worker", import.meta.url), {
        type: "module",
    })),
};
