/**
 * 📝
 *
 * This module includes utilities for creating and managing logger instances
 * with timestamped messages and configurable log levels. Loggers can be
 * customized with a unique name and settings to suit various application
 * needs.
 *
 * ### Features
 *
 * - Timestamped messages with precise formatting.
 * - Configurable log levels (`"off"` or `"all"`).
 * - Support for named logger instances for contextualized logs.
 *
 * ### Example Usage
 *
 * ```ts
 * import { loggerFactory } from "./Logger.js";
 *
 * const logger = loggerFactory.createLogger({
 *   name: "App",
 *   logger: { level: "all" },
 * });
 *
 * logger.log("Application started"); // Logs: `12:34:56:789 [App] Application started`
 * ```
 *
 * @module
 */
import { createTime } from "./Time.js";
export const loggerFactory = {
    createLogger: (deps) => {
        const time = createTime();
        const logger = {
            log: (...messages) => {
                if (deps.logger.level === "off") {
                    return;
                }
                const date = new Date(time.now());
                const hours = date.getHours().toString().padStart(2, "0");
                const minutes = date.getMinutes().toString().padStart(2, "0");
                const seconds = date.getSeconds().toString().padStart(2, "0");
                const milliseconds = date.getMilliseconds().toString().padStart(3, "0");
                const formattedDate = `${hours}:${minutes}:${seconds}:${milliseconds}`;
                globalThis.console.log(`${formattedDate} [${deps.name}]`, ...messages);
            },
        };
        return logger;
    },
};
